package thaumichorizons;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.*;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.AABB;
import net.neoforged.neoforge.gametest.*;
import thaumcraft.aspect.*;
import thaumcraft.research.Knowledge;
import thaumcraft.wand.*;

@GameTestHolder(ThaumicHorizons.ID)
@PrefixGameTestTemplate(false)
public final class SpeciesGameTests {
    static LivingEntity donor(GameTestHelper h,String input){return switch(input){case "sheep"->EntityType.SHEEP.create(h.getLevel());case "cow"->EntityType.COW.create(h.getLevel());case "pig"->EntityType.PIG.create(h.getLevel());case "chicken"->EntityType.CHICKEN.create(h.getLevel());case "cat"->EntityType.OCELOT.create(h.getLevel());case "wolf"->EntityType.WOLF.create(h.getLevel());case "spider"->EntityType.SPIDER.create(h.getLevel());case "horse"->EntityType.HORSE.create(h.getLevel());case "endersteed"->SpeciesHorse.ENDERSTEED.get().create(h.getLevel());default->throw new IllegalArgumentException(input);};}
    @GameTest(template="test/platform") public static void allTwentyTransformationsPreserveIdentityAndInfusions(GameTestHelper h){
        int count=0;for(var recipe:VatRecipes.all())if(recipe.transformation()){
            count++;var input=donor(h,recipe.input());Infusions.add(input,4,null,new AspectList().add(Aspect.ARMOR,16));UUID identity=input.getUUID();var output=recipe.apply(input,UUID.randomUUID(),recipe.cost());h.assertTrue(output!=null,"null result "+recipe.key());String expected=recipe.output().equals("mooshroom")?"minecraft:mooshroom":"thaumichorizons:"+recipe.output();h.assertTrue(BuiltInRegistries.ENTITY_TYPE.getKey(output.getType()).toString().equals(expected),"wrong entity type "+recipe.key());h.assertTrue(output.getUUID().equals(identity)&&Infusions.has(output,4),"transformation lost identity or general infusions "+recipe.key());
            CompoundTag nbt=new CompoundTag();output.save(nbt);Entity loaded=EntityType.loadEntityRecursive(nbt,h.getLevel(),e->e);h.assertTrue(loaded instanceof LivingEntity living&&Infusions.has(living,4)&&living.getUUID().equals(identity),"transformed entity cannot reload "+recipe.key());
        }h.assertValueEqual(count,20,"transformation recipe coverage");h.assertValueEqual(Species.TYPES.size(),18,"distinct custom species coverage");h.succeed();
    }
    @GameTest(template="test/platform") public static void speciesRecipesRejectWrongAnimalsAndRepeatedTransformations(GameTestHelper h){var recipe=VatRecipes.get("species_ore_pig_pig");Player player=h.makeMockPlayer(GameType.SURVIVAL);Knowledge.get(player).addResearch("pigInfusion");var ingredients=recipe.ingredients().stream().map(i->i.displayStacks().getFirst()).toList();h.assertTrue(VatRecipes.find(ingredients,false,EntityType.COW.create(h.getLevel()),player,new int[12])==null,"pig recipe accepted cow");h.assertTrue(VatRecipes.find(ingredients,false,EntityType.PIG.create(h.getLevel()),player,new int[12])==recipe,"pig recipe refused pig");h.assertTrue(VatRecipes.find(ingredients,false,Species.ORE.get().create(h.getLevel()),player,new int[12])==null,"species can be repeatedly transformed");h.assertTrue(Vats.validSubject(Species.TAINT_EATER.get().create(h.getLevel())),"taint-eating pig confused with tainted mob");h.succeed();}
    @GameTest(template="test/platform") public static void chromaticAndSelfShearingTimersMatchLegacy(GameTestHelper h){var chromatic=Species.CHROMATIC.get().create(h.getLevel());chromatic.setPos(h.absolutePos(new BlockPos(2,3,2)).getCenter());chromatic.setColor(DyeColor.BLACK);chromatic.tickCount=30;chromatic.aiStep();h.assertTrue(chromatic.getColor()==DyeColor.WHITE,"chromatic fleece did not wrap after 30 ticks");var shear=Species.SHEARING.get().create(h.getLevel());shear.setPos(chromatic.position());shear.setColor(DyeColor.RED);shear.tickCount=100;shear.aiStep();h.assertTrue(shear.isSheared(),"100-tick automatic shearing failed");var items=h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(shear.blockPosition()).inflate(2),e->e.getItem().is(Items.RED_WOOL));int amount=items.stream().mapToInt(e->e.getItem().getCount()).sum();h.assertTrue(amount>=1&&amount<=3,"wrong automatic fleece yield");shear.ate();h.assertTrue(!shear.isSheared(),"grazing did not restore fleece");h.succeed();}
    @GameTest(template="test/platform") public static void infusedChickensLayProductsAndPersistTimers(GameTestHelper h){
        var scholar=Species.SCHOLAR.get().create(h.getLevel());scholar.setPos(h.absolutePos(new BlockPos(2,3,2)).getCenter());scholar.eggTime=1;scholar.featherTime=1;scholar.aiStep();var gold=Species.GOLD.get().create(h.getLevel());gold.setPos(scholar.position());gold.eggTime=1;gold.aiStep();
        var drops=h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(scholar.blockPosition()).inflate(2));for(Item item:List.of(Content.item("ink_egg"),Content.item("gold_egg"),Items.FEATHER))h.assertValueEqual(drops.stream().filter(e->e.getItem().is(item)).mapToInt(e->e.getItem().getCount()).sum(),1,"wrong chicken product "+item);
        h.assertTrue(scholar.eggTime>=6000&&scholar.eggTime<12000&&scholar.featherTime>=4000&&scholar.featherTime<8000&&gold.eggTime>=8000&&gold.eggTime<16000,"wrong lay interval");var tag=new CompoundTag();scholar.save(tag);var loaded=(Species.InfusedChicken)EntityType.loadEntityRecursive(tag,h.getLevel(),e->e);h.assertValueEqual(loaded.featherTime,scholar.featherTime,"feather timer not saved");h.assertValueEqual(loaded.eggTime,scholar.eggTime,"egg timer not saved");h.succeed();
    }
    @GameTest(template="test/platform") public static void oreBoarConsumesOneStoneAndProducesOneNugget(GameTestHelper h){var pig=Species.ORE.get().create(h.getLevel());pig.setPos(h.absolutePos(new BlockPos(2,3,2)).getCenter());pig.nuggetPercent=99;var item=new ItemEntity(h.getLevel(),pig.getX(),pig.getY(),pig.getZ(),new ItemStack(Items.COBBLESTONE,2));item.setPickUpDelay(0);h.getLevel().addFreshEntity(item);var goal=new Species.PigFeedingGoal(pig,true);h.assertTrue(goal.canUse(),"ore boar did not find loose cobblestone");goal.start();goal.tick();h.assertValueEqual(item.getItem().getCount(),1,"more than one stone consumed");h.assertTrue(pig.nuggetPercent>=0&&pig.nuggetPercent<=14,"wrong digestion progress");var nuggets=h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(pig.blockPosition()).inflate(2),e->e!=item);h.assertValueEqual(nuggets.stream().mapToInt(e->e.getItem().getCount()).sum(),1,"incorrect nugget output");h.succeed();}
    @GameTest(template="test/platform") public static void taintfeederRemovesTaintHealsAndCures(GameTestHelper h){var pig=Species.TAINT_EATER.get().create(h.getLevel());pig.setPos(h.absolutePos(new BlockPos(2,3,2)).getCenter());pig.setHealth(5);BlockPos taint=pig.blockPosition().east();h.getLevel().setBlockAndUpdate(taint,thaumcraft.registry.ModBlocks.FIBROUS_TAINT.get().defaultBlockState());var goal=new Species.PigFeedingGoal(pig,false);h.assertTrue(goal.canUse(),"taintfeeder did not find taint");goal.start();goal.tick();h.assertTrue(h.getLevel().getBlockState(taint).isAir(),"taint block survived feeding");h.assertValueEqual((int)pig.getHealth(),6,"taint meal did not heal one health");pig.addEffect(new net.minecraft.world.effect.MobEffectInstance(thaumcraft.registry.ModEffects.VIS_EXHAUST,100));pig.customServerAiStep();h.assertTrue(!pig.hasEffect(thaumcraft.registry.ModEffects.VIS_EXHAUST),"taintfeeder retained vis exhaustion");h.succeed();}
    @GameTest(template="test/platform") public static void familiarRechargesOneCentivisEachTenTicks(GameTestHelper h){var player=net.neoforged.neoforge.common.util.FakePlayerFactory.get(h.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"THFamiliarTest"));h.getLevel().addNewPlayer(player);player.setPos(h.absolutePos(new BlockPos(2,3,2)).getCenter());var wand=Wands.create(WandRegistry.CAP_GOLD,WandRegistry.ROD_GREATWOOD,false);player.setItemInHand(InteractionHand.MAIN_HAND,wand);var familiar=Species.FAMILIAR.get().create(h.getLevel());familiar.setPos(player.position());familiar.tickCount=10;familiar.customServerAiStep();for(Aspect aspect:Aspect.getPrimalAspects())h.assertValueEqual(Wands.getVis(wand,aspect),1,"familiar charge amount "+aspect);player.discard();h.succeed();}
    @GameTest(template="test/platform") public static void endersteedBonusesDoNotMultiplyAcrossNightmareConversion(GameTestHelper h){var horse=EntityType.HORSE.create(h.getLevel());double health=horse.getAttributeValue(Attributes.MAX_HEALTH),speed=horse.getAttributeValue(Attributes.MOVEMENT_SPEED),jump=horse.getAttributeValue(Attributes.JUMP_STRENGTH);var steed=Species.transform(horse,"endersteed",new AspectList());h.assertTrue(Math.abs(steed.getMaxHealth()-health*5)<.001,"ender health multiplier");h.assertTrue(Math.abs(steed.getAttributeValue(Attributes.MOVEMENT_SPEED)-speed*1.1)<.00001,"ender speed multiplier");h.assertTrue(Math.abs(steed.getAttributeValue(Attributes.JUMP_STRENGTH)-jump*1.25)<.00001,"ender jump multiplier");var nightmare=Species.transform(steed,"nightmare",new AspectList());h.assertTrue(Math.abs(nightmare.getMaxHealth()-health*5)<.001&&nightmare.fireImmune(),"nightmare duplicated bonuses or lost fire immunity");h.succeed();}
    @GameTest(template="test/platform") public static void endersteedStrideFindsGroundAndRejectsSolidDestination(GameTestHelper h){var level=h.getLevel();BlockPos start=h.absolutePos(new BlockPos(2,4,2)),dest=h.absolutePos(new BlockPos(5,4,2));for(BlockPos p:BlockPos.betweenClosed(dest.offset(-1,-1,-1),dest.offset(1,3,1)))level.setBlockAndUpdate(p,p.getY()==dest.getY()-1?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState());var steed=SpeciesHorse.ENDERSTEED.get().create(level);steed.setPos(start.getBottomCenter());h.assertTrue(steed.teleportStride(dest.getX()+.5,dest.getY(),dest.getZ()+.5),"valid stride failed");h.assertTrue(steed.position().distanceToSqr(dest.getBottomCenter())<.01,"stride arrived at wrong height");var before=steed.position();for(BlockPos p:BlockPos.betweenClosed(dest.offset(-1,-3,-1),dest.offset(1,6,1)))level.setBlockAndUpdate(p,Blocks.STONE.defaultBlockState());h.assertTrue(!steed.teleportStride(dest.getX()+.5,dest.getY(),dest.getZ()+.5)&&steed.position().equals(before),"failed stride moved the horse into solid blocks");h.succeed();}
    @GameTest(template="test/platform") public static void chocolateMilkReturnsBucketAndMatchesFoodValues(GameTestHelper h){var cow=Species.CHOCOLATE.get().create(h.getLevel());var player=h.makeMockPlayer(GameType.SURVIVAL);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.BUCKET));cow.mobInteract(player,InteractionHand.MAIN_HAND);var milk=player.getMainHandItem();h.assertTrue(milk.is(Content.item("chocolate_milk")),"cow yielded ordinary milk");var empty=milk.getItem().finishUsingItem(milk,h.getLevel(),player);h.assertTrue(empty.is(Items.BUCKET),"chocolate milk did not return bucket");var bar=Content.item("chocolate_bar").getDefaultInstance().get(net.minecraft.core.component.DataComponents.FOOD);var ice=Content.item("ice_cream").getDefaultInstance().get(net.minecraft.core.component.DataComponents.FOOD);h.assertTrue(bar.nutrition()==1&&Math.abs(bar.saturation()-4)<.001&&ice.nutrition()==3&&Math.abs(ice.saturation()-24)<.001,"legacy chocolate food or saturation values changed");h.succeed();}
}
